def point_type(name, fields, srid_map):
    """Dynamically create a Point subclass.

    Arguments:
        name (str): The name of the new subclass
        fields (dict): A dictionary of field names and types
        srid_map (dict): A dictionary mapping SRID values to coordinate system descriptions

    Returns:
        type: The created Point subclass
    """
    class DynamicPoint(Point):
        _fields = fields
        _srid_map = srid_map

        def __init__(self, srid, *values, **kwargs):
            super().__init__(**kwargs)
            if srid not in self._srid_map:
                raise ValueError(f"Invalid SRID value: {srid}")
            setattr(self, 'srid', srid)
            if len(values) != len(self._fields):
                raise ValueError(f"Expected {len(self._fields)} values, got {len(values)}")
            for field_name, value in zip(self._fields.keys(), values):
                setattr(self, field_name, value)

        def __repr__(self):
            fields_repr = ', '.join(f'{k}={getattr(self, k)}' for k in self._fields.keys())
            return f"{self.__class__.__name__}(srid={self.srid}, {fields_repr})"

    DynamicPoint.__name__ = name
    return DynamicPoint

