def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Create a dictionary to store inheritance information
    inheritance_map = {cls: set(cls.__bases__) for cls in classes}

    # Function to check if a class is a subclass of another
    def is_subclass_of_any(cls, cls_set):
        return any(issubclass(cls, c) for c in cls_set)

    # Remove classes that are subclasses of other classes in the list
    minimal_classes = []
    for cls in classes:
        if not is_subclass_of_any(cls, {c for c in classes if c is not cls}):
