    indent_str = '  ' * indent
    output = f"{indent_str}<{self.__class__.__name__}>"
    if debug:
        output += f" id={self.id}" if hasattr(self, 'id') else ""
    output += "\n"

    if debug and hasattr(self, 'attribs'):
        for key, value in self.attribs.items():
            output += f"{indent_str}  {key}: {value}\n"

    for child in self:
        if isinstance(child, AbstractElement):
            output += child.pretty(indent + 1, debug)
        else:
            output += f"{indent_str}  {child}\n"

    return output

def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    from dateutil.relativedelta import relativedelta

    # Normalize each component to integer values
    normalized_kwargs = {}
    for attr in ['years', 'months', 'days', 'leapdays', 'weeks', 'hours', 'minutes', 'seconds', 'microseconds']:
        value = getattr(self, attr)
        if isinstance(value, float):
            if attr in ['hours', 'minutes', 'seconds', 'microseconds']:
                # Convert fractional days into lower time units
                fractional_part, integer_part = math.modf(value)
                normalized_kwargs[attr] = int(integer_part)
                if attr == 'hours':
                    normalized_kwargs['minutes'] = normalized_kwargs.get('minutes', 0) + int(fractional_part * 24)
                elif attr == 'minutes':
                    normalized_kwargs['seconds'] = normalized_kwargs.get('seconds', 0) + int(fractional_part * 60)
                elif attr == 'seconds':
                    normalized_kwargs['microseconds'] = normalized_kwargs.get('microseconds', 0) + int(fractional_part * 1_000_000)
            elif attr == 'days':
                fractional_part, integer_part = math.modf(value)
                normalized_kwargs[attr] = int(integer_part)
                # Convert fractional days into hours
                normalized_kwargs['hours'] = normalized_kwargs.get('hours', 0) + int(fractional_part * 24)
        else:
            normalized_kwargs[attr] = value

    # Return the new normalized relativedelta object
    return relativedelta(**normalized_kwargs)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys

    if sys.version_info[0] < 3:
        def wrapped(*args, **kwargs):
            result = namefunc(*args, **kwargs)
            return tuple(item.encode('utf-8') for item in result)
        return wrapped
    else:
        return namefunc

