def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    import argparse
    import borgmatic.commands.borgmatic  # Assuming borgmatic's main command-line interface module is here

    def format_completion(parser, parent_command=''):
        lines = []
        if parent_command:
            command = parent_command + ' '
        else:
            command = ''

        # Add command itself
        if parent_command:
            lines.append(f"complete -W '{' '.join(parser.prog.split())[1:]}' {parent_command}")

        # Add options for the command
        for action in parser._actions:
            if action.option_strings:
                lines.append(f"complete -W '{' '.join(action.option_strings)}' {command}")

        # Recurse for subparsers
        for subparsers_action in parser._actions:
            if isinstance(subparsers_action, argparse._SubParsersAction):
                for subparser_name, subparser in subparsers_action.choices.items():
                    lines.extend(format_completion(subparser, command + subparser_name))

        return lines

    main_parser = borgmatic.commands.borgmatic.generate_argument_parser()
    completion_lines = format_completion(main_parser)
    return "\n".join(completion_lines)

