from typing import Dict, Any

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Attempt to parse as JSON
        parsed_data = json.loads(document)
        return _parse_json_webfinger(parsed_data)
    except json.JSONDecodeError:
        # If JSON parsing fails, attempt to parse as XRD
        try:
            parsed_data = ET.fromstring(document)
            return _parse_xrd_webfinger(parsed_data)
        except ET.ParseError:
            raise ValueError("The provided document is neither valid JSON nor XRD.")

def _parse_json_webfinger(js_data: Any) -> Dict:
    """
    Internal method to parse parsed JSON webfinger data.
    """
    if not isinstance(js_data, dict):
        raise ValueError("JSON data is not in the expected format.")

    # Assuming the JSON structure has 'links' and 'subjects' keys, modify as necessary
    links = js_data.get('links', [])
    subjects = js_data.get('subjects', [])

    parsed_links = []
    for link in links:
        if isinstance(link, dict):
            rel = link.get('rel')
            href = link.get('href')
            if rel and href:
                parsed_links.append({'rel': rel, 'href': href})

    return {
        'subjects': subjects,
        'links': parsed_links
    }

def _parse_xrd_webfinger(xml_data: ET.Element) -> Dict:
    """
    Internal method to parse parsed XRD webfinger data.
    """
    subjects = [node.text for node in xml_data.findall('.//Subject')]
    links = []

    for link in xml_data.findall('.//Link'):
        rel = link.attrib.get('rel')
        href = link.attrib.get('href')
        if rel and href:
            links.append({'rel': rel, 'href': href})

    return {
        'subjects': subjects,
        'links': links
    }

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    from xml.etree import ElementTree as ET

    try:
        # Construct the webfinger URL
        webfinger_url = f"https://diaspora.example.com/.well-known/webfinger?resource={handle}"

        # Send a GET request to the webfinger URL
        response = requests.get(webfinger_url)
        response.raise_for_status()  # Raise an exception for 4xx or 5xx status codes

        # Parse the XML response
        root = ET.fromstring(response.content)

        # Extract the relevant information into a dictionary
        result = {}
        for link in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
            rel = link.get('rel')
            href = link.get('href')
            if rel and href:
                result[rel] = href

        return result

    except requests.exceptions.RequestException as e:
        print(f"Request failed: {e}")
        return {}
    except ET.ParseError as e:
        print(f"XML parsing failed: {e}")
        return {}

